function r(e){return String(e??"").toLowerCase().replace(/[^a-z0-9]/g,"")}function a(e){return new Set([e.id,e.node,e.sensorDataName,e.sensorNode,e.sensorId,e.sensor_id].map(r).filter(Boolean))}function t(e){return new Set([e.node,e.id,e.bin,e.binId,e.bin_id].map(r).filter(Boolean))}function f(e){const i=t(e);return["node1","node01","node=1","node=01"].some(n=>i.has(n))?"bin10":null}function c(e,i){const n=t(e),d=a(i),o=f(e);return o&&n.add(o),Array.from(n).some(s=>d.has(s))}function u(e,i){return i.some(n=>c(e,n))}export{u as a,c as i};
